/**
 * Called by the pipeline when a run ends: POST /services/apexrest/release-relay/v1/status
 * with {"request": "REL-00012"}. It doesn't trust anything else in the body: it reads the
 * results from the Git provider, exactly as the status sync does, and saves them. So the
 * release updates the moment a step finishes, without waiting for the scheduled sync.
 *
 * The pipeline signs in with the source org's JWT login (its environment's SF_* secrets);
 * that user needs the Release Relay User permission set, which grants this class.
 */
@RestResource(urlMapping='/release-relay/v1/status')
global with sharing class RlyStatusService {

    private static final Pattern RELEASE_NAME = Pattern.compile('^REL-\\d{5,10}$');

    global class Result {
        global String request;
        global String status;
        global String message;
    }

    @HttpPost
    global static Result notifyStatus() {
        Result out = new Result();
        RestRequest rr = RestContext.request;
        String name;
        try {
            Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(rr.requestBody.toString());
            name = body.get('request') == null ? null : String.valueOf(body.get('request')).trim();
        } catch (Exception e) {
            name = null;
        }
        if (name == null || !RELEASE_NAME.matcher(name).matches()) {
            RestContext.response.statusCode = 400;
            out.message = 'Send {"request": "REL-00012"}.';
            return out;
        }
        out.request = name;
        List<RLY_Release__c> reqs = new Data().byName(name);
        if (reqs.isEmpty()) {
            RestContext.response.statusCode = 404;
            out.message = 'No release ' + name + ' in this org.';
            return out;
        }
        RlySyncJob.syncAndSave(reqs);
        out.status = new Data().byName(name)[0].Status__c;
        return out;
    }

    private without sharing class Data {
        public List<RLY_Release__c> byName(String name) {
            return [SELECT Id, Name, Status__c, Connection__c, Connection_Type__c, Source_Branch__c, Target_Branch__c, Target_Environment__c,
                           Source_Environment__c, Title__c, Mode__c, Pending_Run__c, Last_Synced__c,
                           Run_ID__c, Run_URL__c, PR_Number__c, PR_URL__c, Error_Message__c, Checks_Requested__c,
                           Scan_Status__c, Scan_Violations__c, Scan_Blocking__c, Scan_Result__c,
                           Validation_Status__c, Validation_Result__c, Approval_Status__c, Approved_On__c,
                           Merge_Commit__c, Deploy_Status__c, Deploy_Result__c
                    FROM RLY_Release__c WHERE Name = :name LIMIT 1];
        }
    }
}
